//# sourceMappingURL=main.d3517216.js.map

window.openBackupModal = function() {
    function getAdminToken() {
        let direct = localStorage.getItem("token");
        if (direct) return direct;
        for (let i = 0; i < localStorage.length; i++) {
            let key = localStorage.key(i);
            if (key && (key.includes("appData") || key.includes("token") || key.includes("auth"))) {
                try {
                    let val = localStorage.getItem(key);
                    if (val && (val.startsWith("{") || val.startsWith("["))) {
                        let parsed = JSON.parse(val);
                        if (parsed?.value?.token) return parsed.value.token;
                        if (parsed?.token) return parsed.token;
                    } else if (val && val.length > 20 && !val.includes(" ")) {
                        return val;
                    }
                } catch(e) {}
            }
        }
        return "";
    }

    let existing = document.getElementById("backup-restore-modal");
    if (existing) { existing.style.display = "flex"; return; }

    let modal = document.createElement("div");
    modal.id = "backup-restore-modal";
    modal.style.position = "fixed";
    modal.style.top = "0";
    modal.style.left = "0";
    modal.style.width = "100%";
    modal.style.height = "100%";
    modal.style.backgroundColor = "rgba(0,0,0,0.75)";
    modal.style.backdropFilter = "blur(8px)";
    modal.style.display = "flex";
    modal.style.alignItems = "center";
    modal.style.justifyContent = "center";
    modal.style.zIndex = "99999";
    modal.style.fontFamily = "Vazirmatn, Segoe UI, sans-serif";

    modal.innerHTML = `
        <div style="background: #1e293b; color: #f8fafc; border: 1px solid rgba(255,255,255,0.12); border-radius: 20px; width: 90%; max-width: 460px; padding: 26px; box-shadow: 0 20px 40px rgba(0,0,0,0.6); position: relative; direction: rtl;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 20px; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 14px;">
                <div style="display: flex; align-items: center; gap: 10px;">
                    <span style="font-size: 1.5rem;">💾</span>
                    <h3 style="margin: 0; font-size: 1.2rem; font-weight: 700; color: #38bdf8;">پشتیبان‌گیری و بازگردانی دیتابیس</h3>
                </div>
                <button id="close-backup-modal-btn" style="background: none; border: none; color: #94a3b8; font-size: 1.5rem; cursor: pointer; line-height: 1;">&times;</button>
            </div>
            
            <div style="display: flex; flex-direction: column; gap: 16px;">
                <!-- Download Card -->
                <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 14px; padding: 16px;">
                    <div style="font-weight: 600; font-size: 0.95rem; margin-bottom: 6px; color: #38bdf8;">📥 دانلود فایل پشتیبان (Backup)</div>
                    <p style="font-size: 0.8rem; color: #94a3b8; margin: 0 0 12px 0; line-height: 1.5;">تهیه نسخه پشتیبان کامل از تمامی کاربران، اکانت‌ها، هاست‌ها و تنظیمات دیتابیس.</p>
                    <button id="btn-do-backup" style="width: 100%; padding: 10px 16px; border-radius: 10px; border: none; background: linear-gradient(135deg, #0284c7, #2563eb); color: #fff; font-weight: 700; font-size: 0.88rem; cursor: pointer; transition: all 0.2s;">
                        دانلود backup.sql
                    </button>
                </div>

                <!-- Restore Card -->
                <div style="background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.06); border-radius: 14px; padding: 16px;">
                    <div style="font-weight: 600; font-size: 0.95rem; margin-bottom: 6px; color: #f59e0b;">📤 بازگردانی پشتیبان (Restore)</div>
                    <p style="font-size: 0.8rem; color: #94a3b8; margin: 0 0 12px 0; line-height: 1.5;">انتخاب فایل backup.sql قبلی و بازگردانی تمامی اطلاعات روی پنل.</p>
                    <input type="file" id="backup-file-input" accept=".sql" style="display: none;" />
                    <button id="btn-select-restore" style="width: 100%; padding: 10px 16px; border-radius: 10px; border: 1px dashed rgba(245, 158, 11, 0.4); background: rgba(245, 158, 11, 0.1); color: #fbbf24; font-weight: 700; font-size: 0.88rem; cursor: pointer; transition: all 0.2s;">
                        انتخاب فایل و بازگردانی
                    </button>
                </div>
            </div>

            <div id="backup-status-text" style="margin-top: 16px; font-size: 0.82rem; text-align: center; min-height: 20px; font-weight: 600;"></div>
        </div>
    `;

    document.body.appendChild(modal);

    document.getElementById("close-backup-modal-btn").onclick = function() {
        modal.style.display = "none";
    };

    modal.onclick = function(e) {
        if (e.target === modal) modal.style.display = "none";
    };

    // Download backup logic
    document.getElementById("btn-do-backup").onclick = function() {
        let status = document.getElementById("backup-status-text");
        status.style.color = "#38bdf8";
        status.innerText = "در حال ایجاد و دانلود فایل پشتیبان...";

        let token = getAdminToken();
        let downloadUrl = "/api/system/backup?token=" + encodeURIComponent(token);

        fetch(downloadUrl, {
            headers: token ? { "Authorization": "Bearer " + token } : {}
        })
        .then(async res => {
            if (!res.ok) {
                let res2 = await fetch("/api/backup?token=" + encodeURIComponent(token), {
                    headers: token ? { "Authorization": "Bearer " + token } : {}
                });
                if (res2.ok) return res2.blob();

                let errDetail = "";
                try {
                    let j = await res.json();
                    errDetail = j.detail || "";
                } catch(e) {
                    try {
                        let j2 = await res2.json();
                        errDetail = j2.detail || "";
                    } catch(e2) {}
                }
                throw new Error(errDetail || ("خطا در ایجاد بکاپ (کد " + res.status + ")"));
            }
            return res.blob();
        })
        .then(blob => {
            let url = window.URL.createObjectURL(blob);
            let a = document.createElement("a");
            a.style.display = "none";
            a.href = url;
            a.download = "backup.sql";
            document.body.appendChild(a);
            a.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(a);

            status.style.color = "#34d399";
            status.innerText = "فایل backup.sql با موفقیت دریافت و ذخیره شد.";
        })
        .catch(err => {
            status.style.color = "#f43f5e";
            status.innerText = err.message || "خطا در دانلود فایل پشتیبان";
        });
    };

    // Restore backup logic
    let fileInput = document.getElementById("backup-file-input");
    document.getElementById("btn-select-restore").onclick = function() {
        fileInput.value = "";
        fileInput.click();
    };

    fileInput.onchange = function(e) {
        let file = e.target.files[0];
        if (!file) return;

        if (!file.name.endsWith(".sql")) {
            alert("لطفاً فقط فایل با پسوند .sql انتخاب کنید.");
            return;
        }

        if (!confirm("آیا از بازگردانی این فایل پشتیبان اطمینان دارید؟ اطلاعات دیتابیس جایگزین خواهند شد.")) {
            return;
        }

        let status = document.getElementById("backup-status-text");
        status.style.color = "#fbbf24";
        status.innerText = "در حال آپلود و بازگردانی دیتابیس... لطفاً صبور باشید.";

        let formData = new FormData();
        formData.append("file", file);

        let token = getAdminToken();
        let authHeader = token ? { "Authorization": "Bearer " + token } : {};

        let xhr = new XMLHttpRequest();
        xhr.open("POST", "/api/system/restore", true);
        if (token) xhr.setRequestHeader("Authorization", "Bearer " + token);

        xhr.timeout = 900000; // 15 minutes timeout for large backups
        xhr.upload.onprogress = function(event) {
            if (event.lengthComputable) {
                let percent = Math.round((event.loaded / event.total) * 100);
                if (percent < 100) {
                    status.style.color = "#fbbf24";
                    status.innerText = "در حال ارسال فایل به سرور (" + percent + "%)... لطفاً صفحه را نبندید.";
                } else {
                    status.style.color = "#38bdf8";
                    status.innerText = "فایل به سرور منتقل شد. در حال اعمال در پایگاه داده PostgreSQL... لطفاً چند لحظه شکیبا باشید.";
                }
            }
        };

        xhr.onload = function() {
            if (xhr.status >= 200 && xhr.status < 300) {
                status.style.color = "#34d399";
                status.innerText = "بازگردانی با موفقیت انجام شد! پنل در حال بارگذاری مجدد است...";
                setTimeout(() => { window.location.reload(); }, 2500);
            } else {
                let errMsg = "خطا در بازگردانی (کد " + xhr.status + ")";
                try {
                    let j = JSON.parse(xhr.responseText);
                    errMsg = j.detail || errMsg;
                } catch(e) {}
                status.style.color = "#f43f5e";
                status.innerText = "خطا: " + errMsg;
            }
        };

        xhr.onerror = function() {
            status.style.color = "#f43f5e";
            status.innerText = "خطای شبکه یا قطعی اینترنت حین ارسال فایل.";
        };

        xhr.send(formData);
    };
};


window.showSubLinkModal = function(url, row) {
    let existing = document.getElementById("sub-link-copy-modal");
    if (existing) { existing.remove(); }

    let clientTitle = (row && (row.user_title || row.service_title || row.email || row.full_name)) || "کلاینت";

    let modal = document.createElement("div");
    modal.id = "sub-link-copy-modal";
    modal.style.position = "fixed";
    modal.style.top = "0";
    modal.style.left = "0";
    modal.style.width = "100%";
    modal.style.height = "100%";
    modal.style.backgroundColor = "rgba(0,0,0,0.75)";
    modal.style.backdropFilter = "blur(8px)";
    modal.style.display = "flex";
    modal.style.alignItems = "center";
    modal.style.justifyContent = "center";
    modal.style.zIndex = "999999";
    modal.style.fontFamily = "Vazirmatn, Segoe UI, sans-serif";

    modal.innerHTML = `
        <div style="background: #1e293b; color: #f8fafc; border: 1px solid rgba(255,255,255,0.12); border-radius: 20px; width: 92%; max-width: 480px; padding: 24px; box-shadow: 0 20px 40px rgba(0,0,0,0.6); position: relative; direction: rtl;">
            <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 16px; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 12px;">
                <div style="display: flex; align-items: center; gap: 8px;">
                    <span style="font-size: 1.4rem;">🔗</span>
                    <h3 style="margin: 0; font-size: 1.15rem; font-weight: 700; color: #38bdf8;">لینک سابسکریپشن کلاینت</h3>
                </div>
                <button id="close-sub-link-modal-btn" style="background: none; border: none; color: #94a3b8; font-size: 1.6rem; cursor: pointer; line-height: 1;">&times;</button>
            </div>

            <div style="font-size: 0.86rem; color: #cbd5e1; margin-bottom: 12px;">
                نام کاربر / کلاینت: <strong style="color: #38bdf8;">${clientTitle}</strong>
            </div>

            <div style="margin-bottom: 14px;">
                <div style="position: relative; display: flex; align-items: center;">
                    <input id="sub-url-input-field" type="text" value="${url}" readonly 
                           style="width: 100%; padding: 12px 14px; background: rgba(0,0,0,0.4); border: 1px solid rgba(255,255,255,0.15); border-radius: 12px; color: #38bdf8; font-size: 0.85rem; font-family: monospace; direction: ltr; outline: none; cursor: pointer;" />
                </div>
            </div>

            <div style="display: flex; gap: 10px; margin-bottom: 16px;">
                <button id="btn-copy-sub-url" style="flex: 2; padding: 11px 16px; border-radius: 12px; border: none; background: linear-gradient(135deg, #0284c7, #2563eb); color: #fff; font-weight: 700; font-size: 0.9rem; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 6px; box-shadow: 0 4px 14px rgba(2,132,199,0.4);">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path></svg>
                    <span id="btn-copy-sub-text">کپی کردن لینک</span>
                </button>
                <a href="${url}" target="_blank" rel="noopener noreferrer" style="flex: 1; padding: 11px 12px; border-radius: 12px; border: 1px solid rgba(255,255,255,0.12); background: rgba(255,255,255,0.05); color: #e2e8f0; font-weight: 600; font-size: 0.85rem; text-decoration: none; display: flex; align-items: center; justify-content: center; gap: 6px; text-align: center;">
                    🌐 باز کردن
                </a>
            </div>

            <div style="display: flex; flex-direction: column; align-items: center; justify-content: center; background: rgba(0,0,0,0.25); border: 1px solid rgba(255,255,255,0.06); border-radius: 14px; padding: 14px;">
                <img src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&margin=2&data=${encodeURIComponent(url)}" 
                     alt="QR Code" style="width: 130px; height: 130px; border-radius: 10px; background: #fff; padding: 6px;" />
                <span style="font-size: 0.76rem; color: #94a3b8; margin-top: 8px;">اسکن مستقیم با گوشی و اپلیکیشن‌های V2Ray</span>
            </div>
        </div>
    `;

    document.body.appendChild(modal);

    let inputField = document.getElementById("sub-url-input-field");
    inputField.onclick = function() { inputField.select(); };

    function doCopy() {
        inputField.focus();
        inputField.select();
        let ok = false;
        if (navigator.clipboard && window.isSecureContext) {
            navigator.clipboard.writeText(url).then(() => { ok = true; }).catch(() => {});
        }
        try {
            ok = document.execCommand("copy");
        } catch(e) {}
        let btnText = document.getElementById("btn-copy-sub-text");
        btnText.innerText = "✓ کپی شد!";
        setTimeout(() => { btnText.innerText = "کپی کردن لینک"; }, 2000);
    }

    document.getElementById("btn-copy-sub-url").onclick = doCopy;

    document.getElementById("close-sub-link-modal-btn").onclick = function() {
        modal.remove();
    };

    modal.onclick = function(e) {
        if (e.target === modal) modal.remove();
    };

    // Auto copy on open
    doCopy();
};
